  font-family: "Fraunces", Georgia, serif;
  font-size: 1.3rem; letter-spacing: -0.01em;
}
.brand:hover { text-decoration: none; }
.brand__mark { font-size: 1.4rem; color: var(--accent); }

.primary-nav { margin-left: 1rem; }
.primary-nav ul {
  display: flex; gap: 1.5rem; list-style: none; padding: 0; margin: 0;
}
.primary-nav a { font-size: 0.95rem; color: var(--ink-2); }
.primary-nav a:hover { color: var(--ink); }

.header-actions {
  display: flex; gap: .25rem; margin-left: auto; align-items: center;
}
.icon-btn {
  appearance: none; background: transparent; border: 0;
  width: 40px; height: 40px; display: inline-grid; place-items: center;
  color: var(--ink); border-radius: 999px; cursor: pointer;
  position: relative;
  transition: background-color .15s ease;
}
.icon-btn:hover { background: var(--soft); }
.cart-badge {
  position: absolute; top: 4px; right: 4px;
  background: var(--accent); color: #fff;
  font-size: 0.65rem; font-weight: 600;
  min-width: 18px; height: 18px; padding: 0 5px;
  border-radius: 999px; display: grid; place-items: center;
  line-height: 1;
}

@media (max-width: 720px) {
  .primary-nav { display: none; }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: .85rem 1.4rem;
  border-radius: 999px;
  font-weight: 500; font-size: .95rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform .15s ease, background-color .15s ease, color .15s ease;
  text-decoration: none;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn--primary { background: var(--ink); color: #fff; }
.btn--primary:hover { background: var(--accent); }
.btn--ghost { background: transparent; color: var(--ink); border-color: var(--ink); }
.btn--ghost:hover { background: var(--ink); color: #fff; }

/* ---------- Hero ---------- */
.hero { padding: clamp(2rem, 6vw, 5rem) 0 clamp(2.5rem, 7vw, 6rem); }
.hero-inner {
  display: grid; gap: clamp(2rem, 4vw, 4rem);
  grid-template-columns: 1.05fr 1fr;
  align-items: center;
}
@media (max-width: 880px) { .hero-inner { grid-template-columns: 1fr; } }

.eyebrow {
  text-transform: uppercase;
  font-size: .75rem; letter-spacing: .18em;
  color: var(--muted); margin-bottom: 1rem;
  font-weight: 500;
}
.eyebrow--light { color: rgba(255,255,255,.75); }

.hero-copy h1 .accent {
  font-style: italic; color: var(--accent);
}
.hero-lede {
  margin-top: 1.25rem;
  font-size: 1.1rem; max-width: 46ch; color: var(--ink-2);
}
.hero-cta {
  display: flex; flex-wrap: wrap; gap: .75rem;
  margin-top: 2rem;
}

.hero-art {
  position: relative; aspect-ratio: 1 / 1;
  min-height: 320px;
}
.hero-card {
  position: absolute; border-radius: var(--radius);
  box-shadow: var(--shadow-md);
  background-size: cover; background-position: center;
}
.hero-card--1 {
  inset: 0 30% 25% 0;
  background:
    linear-gradient(135deg, rgba(0,0,0,.05), rgba(0,0,0,0)),
    radial-gradient(circle at 30% 30%, #d8c8a8, #a48a64 70%);
}
.hero-card--2 {
  inset: 18% 0 18% 35%;
  background:
    linear-gradient(160deg, rgba(255,255,255,.15), rgba(0,0,0,.1)),
    linear-gradient(180deg, #2f5d4f, #1d3a31);
}
.hero-card--3 {
  inset: 55% 50% 0 5%;
  background:
    radial-gradient(circle at 70% 30%, #f3e4d0, #d8b894 70%);
}

/* ---------- Strip ---------- */
.strip {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--bg-alt);
  overflow: hidden;
}
.strip ul {
  display: flex; gap: 3rem; list-style: none;
  padding: .9rem 1.5rem; margin: 0;
  justify-content: center; flex-wrap: wrap;
  font-size: .85rem; color: var(--ink-2);
}

/* ---------- Sections ---------- */
section { padding: clamp(3rem, 7vw, 5.5rem) 0; }

.section-head {
  display: flex; align-items: end; justify-content: space-between;
  gap: 1.5rem; flex-wrap: wrap;
  margin-bottom: 2.5rem;
}
.link-arrow {
  font-size: .95rem; color: var(--ink-2);
  border-bottom: 1px solid var(--line);
  padding-bottom: 2px;
}
.link-arrow:hover { color: var(--ink); border-color: var(--ink); text-decoration: none; }

/* ---------- Categories ---------- */
.cat-grid {
  display: grid; gap: var(--gap); list-style: none; padding: 0; margin: 0;
  grid-template-columns: repeat(4, 1fr);
}
@media (max-width: 880px) { .cat-grid { grid-template-columns: repeat(2, 1fr); } }

.cat-card {
  display: flex; align-items: end; padding: 1.2rem;
  aspect-ratio: 4 / 5; border-radius: var(--radius);
  color: #fff; font-family: "Fraunces", Georgia, serif;
  font-size: 1.4rem; letter-spacing: -0.01em;
  position: relative; overflow: hidden;
  transition: transform .25s ease;
}
.cat-card:hover { transform: translateY(-3px); text-decoration: none; }
.cat-card span { position: relative; z-index: 1; }
.cat-card::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,.55));
}
.cat--home    { background: linear-gradient(135deg, #b89c7a, #6b5239); }
.cat--wear    { background: linear-gradient(135deg, #2f5d4f, #1c3a31); }
.cat--desk    { background: linear-gradient(135deg, #c8623c, #8a3e22); }
.cat--kitchen { background: linear-gradient(135deg, #d8c8a8, #8a7350); }

/* ---------- Featured products ---------- */
.featured { background: var(--bg-alt); }

.filters { display: flex; flex-wrap: wrap; gap: .5rem; }
.chip {
  appearance: none; background: transparent;
  border: 1px solid var(--line);
  padding: .5rem 1rem; border-radius: 999px;
  font-size: .85rem; color: var(--ink-2);
  cursor: pointer;
  transition: background-color .15s ease, color .15s ease, border-color .15s ease;
}
.chip:hover { border-color: var(--ink-2); color: var(--ink); }
.chip.is-active {
  background: var(--ink); color: #fff; border-color: var(--ink);
}

.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid; gap: var(--gap);
  grid-template-columns: repeat(4, 1fr);
}
@media (max-width: 980px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px) { .product-grid { grid-template-columns: repeat(2, 1fr); } }

.product {
  display: flex; flex-direction: column;
  background: var(--bg-alt);
  border-radius: var(--radius);
  position: relative;
}
.product__media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--soft);
}
.product__art {
  position: absolute; inset: 0;
  transition: transform .5s ease;
}
.product:hover .product__art { transform: scale(1.04); }
.product__tag {
  position: absolute; top: .75rem; left: .75rem;
  background: #fff; color: var(--ink);
  font-size: .7rem; font-weight: 600;
  padding: .25rem .55rem; border-radius: 999px;
  letter-spacing: .05em; text-transform: uppercase;
}
.product__tag--sale { background: var(--warm); color: #fff; }

.product__add {
  position: absolute; right: .75rem; bottom: .75rem;
  appearance: none; border: 0; cursor: pointer;
  width: 40px; height: 40px; border-radius: 999px;
  background: #fff; color: var(--ink);
  display: grid; place-items: center;
  box-shadow: var(--shadow-sm);
  opacity: 0; transform: translateY(6px);
  transition: opacity .2s ease, transform .2s ease, background-color .15s ease;
}
.product:hover .product__add,
.product__add:focus-visible {
  opacity: 1; transform: translateY(0);
}
.product__add:hover { background: var(--ink); color: #fff; }

.product__body {
  padding: 1rem .25rem 0;
  display: flex; flex-direction: column; gap: .25rem;
}
.product__cat {
  font-size: .75rem; color: var(--muted);
  text-transform: uppercase; letter-spacing: .12em;
}
.product__name {
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.05rem; color: var(--ink);
}
.product__price {
  display: flex; gap: .5rem; align-items: baseline;
  font-size: .95rem; color: var(--ink);
  margin-top: .15rem;
}
.product__price del { color: var(--muted); font-size: .85rem; }

/* ---------- Deals ---------- */
.deals {
  background: linear-gradient(180deg, #1d3a31, #142a23);
  color: #fff;
}
.deals .section-head h2 { color: #fff; }
.deals .link-arrow { color: rgba(255,255,255,.8); border-color: rgba(255,255,255,.25); }
.deals .link-arrow:hover { color: #fff; border-color: #fff; }

.countdown {
  display: flex; gap: .5rem;
}
.countdown span {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-sm);
  padding: .55rem .7rem;
  display: flex; flex-direction: column; align-items: center;
  min-width: 56px;
}
.countdown strong {
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.4rem; font-weight: 500;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.countdown em {
  font-style: normal; font-size: .65rem;
  text-transform: uppercase; letter-spacing: .12em;
  color: rgba(255,255,255,.7); margin-top: .35rem;
}

.deals-grid {
  display: grid; gap: var(--gap);
  grid-template-columns: 1.3fr 1fr 1fr;
  grid-template-rows: auto;
}
@media (max-width: 880px) { .deals-grid { grid-template-columns: 1fr; } }

.deal {
  background: rgba(255,255,255,.04);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
}
.deal__art {
  aspect-ratio: 16 / 11;
  background:
    radial-gradient(circle at 30% 30%, #d8c8a8, #6b5239 80%);
}
.deal--big { grid-row: span 2; }
.deal--big .deal__art {
  aspect-ratio: 4 / 5;
  background:
    linear-gradient(135deg, rgba(0,0,0,.1), rgba(0,0,0,0)),
    radial-gradient(circle at 30% 40%, #ede7dc, #b89c7a 75%);
}
.deal__art--ceramic {
  background: radial-gradient(circle at 60% 40%, #c8623c, #6b2a14) !important;
}
.deal__art--candle {
  background: radial-gradient(circle at 40% 30%, #f3e4d0, #8a7350) !important;
}
.deal__body {
  padding: 1.5rem; display: flex; flex-direction: column; gap: .65rem;
  flex: 1;
}
.deal__body h3 { font-size: 1.4rem; color: #fff; }
.deal__body p { color: rgba(255,255,255,.75); font-size: .95rem; }
.deal__body .btn { align-self: flex-start; margin-top: .5rem; background: #fff; color: var(--ink); }
.deal__body .btn:hover { background: var(--warm); color: #fff; }
.badge {
  display: inline-block; align-self: flex-start;
  background: var(--warm); color: #fff;
  font-size: .7rem; font-weight: 600;
  padding: .3rem .6rem; border-radius: 999px;
  text-transform: uppercase; letter-spacing: .08em;
}
.badge--soft {
  background: rgba(255,255,255,.12);
  color: #fff;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid; gap: var(--gap);
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
}
.post--feature { grid-row: span 2; }
@media (max-width: 980px) {
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .post--feature { grid-row: auto; grid-column: span 2; }
}
@media (max-width: 600px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .post--feature { grid-column: auto; }
}

.post {
  display: flex; flex-direction: column;
  background: var(--bg-alt);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .2s ease, box-shadow .2s ease;
}
.post:hover { transform: translateY(-2px); box-shadow: var(--shadow-sm); }
.post__media {
  display: block;
  aspect-ratio: 16/10;
  background-size: cover; background-position: center;
}
.post--feature .post__media { aspect-ratio: 4/5; }
.post__media--1 { background: linear-gradient(135deg, #d8c8a8, #6b5239); }
.post__media--2 { background: linear-gradient(135deg, #2f5d4f, #1d3a31); }
.post__media--3 { background: linear-gradient(135deg, #c8623c, #6b2a14); }
.post__media--4 { background: linear-gradient(135deg, #ede7dc, #b89c7a); }

.post__body { padding: 1.25rem 1.4rem 1.5rem; display: flex; flex-direction: column; gap: .5rem; }
.post__meta { font-size: .75rem; color: var(--muted); text-transform: uppercase; letter-spacing: .12em; }
.post__body h3 a { color: var(--ink); }
.post__body p { color: var(--ink-2); font-size: .95rem; }

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--soft);
  border-top: 1px solid var(--line);
}
.newsletter-inner {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 2rem; align-items: center;
}
@media (max-width: 800px) { .newsletter-inner { grid-template-columns: 1fr; } }

.news-form {
  display: grid; grid-template-columns: 1fr auto;
  gap: .5rem;
  background: #fff;
  padding: .35rem .35rem .35rem 1rem;
  border-radius: 999px;
  border: 1px solid var(--line);
}
.news-form input {
  border: 0; outline: none; background: transparent;
  padding: .85rem 0;
  font: inherit;
  color: var(--ink);
  min-width: 0;
}
.news-form input:focus-visible { outline: 0; }
.news-form:focus-within { border-color: var(--ink); }
.news-help {
  grid-column: 1 / -1;
  font-size: .75rem; color: var(--muted);
  padding: .25rem 1rem 0;
}
.news-help.is-error { color: #b3261e; }
.news-help.is-success { color: var(--accent); }

/* ---------- Footer ---------- */
.site-footer {
  background: var(--ink);
  color: #d6d3ce;
  padding-top: 3rem;
}
.footer-grid {
  display: grid; gap: 2rem;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  padding-bottom: 2rem;
}
@media (max-width: 780px) { .footer-grid { grid-template-columns: 1fr 1fr; } }
.footer-brand p { margin-top: .75rem; max-width: 32ch; color: #a9a59e; }
.footer-brand .brand__mark { color: #fff; font-size: 1.6rem; }
.site-footer h2 {
  font-family: inherit;
  font-size: .8rem; text-transform: uppercase; letter-spacing: .15em;
  color: #fff; margin-bottom: 1rem; font-weight: 600;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: .55rem; }
.site-footer a { color: #d6d3ce; font-size: .92rem; }
.site-footer a:hover { color: #fff; }
.footer-bottom {
  display: flex; justify-content: space-between; gap: 1rem;
  padding: 1.25rem 0;
  border-top: 1px solid #2c2a27;
  color: #807a72;
}

/* High contrast / forced colors */
@media (forced-colors: active) {
  .btn, .chip, .icon-btn, .cat-card, .product, .post, .deal {
    border: 1px solid CanvasText;
  }
}

