+  display: inline-block; align-self: flex-start;
+  background: var(--warm); color: #fff;
+  font-size: .7rem; font-weight: 600;
+  padding: .3rem .6rem; border-radius: 999px;
+  text-transform: uppercase; letter-spacing: .08em;
+}
+.badge--soft {
+  background: rgba(255,255,255,.12);
+  color: #fff;
+}
+
+/* ---------- Editorial ---------- */
+.editorial-grid {
+  display: grid; gap: var(--gap);
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-template-rows: auto auto;
+}
+.post--feature { grid-row: span 2; }
+@media (max-width: 980px) {
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .post--feature { grid-row: auto; grid-column: span 2; }
+}
+@media (max-width: 600px) {
+  .editorial-grid { grid-template-columns: 1fr; }
+  .post--feature { grid-column: auto; }
+}
+
+.post {
+  display: flex; flex-direction: column;
+  background: var(--bg-alt);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  transition: transform .2s ease, box-shadow .2s ease;
+}
+.post:hover { transform: translateY(-2px); box-shadow: var(--shadow-sm); }
+.post__media {
+  display: block;
+  aspect-ratio: 16/10;
+  background-size: cover; background-position: center;
+}
+.post--feature .post__media { aspect-ratio: 4/5; }
+.post__media--1 { background: linear-gradient(135deg, #d8c8a8, #6b5239); }
+.post__media--2 { background: linear-gradient(135deg, #2f5d4f, #1d3a31); }
+.post__media--3 { background: linear-gradient(135deg, #c8623c, #6b2a14); }
+.post__media--4 { background: linear-gradient(135deg, #ede7dc, #b89c7a); }
+
+.post__body { padding: 1.25rem 1.4rem 1.5rem; display: flex; flex-direction: column; gap: .5rem; }
+.post__meta { font-size: .75rem; color: var(--muted); text-transform: uppercase; letter-spacing: .12em; }
+.post__body h3 a { color: var(--ink); }
+.post__body p { color: var(--ink-2); font-size: .95rem; }
+
+/* ---------- Newsletter ---------- */
+.newsletter {
+  background: var(--soft);
+  border-top: 1px solid var(--line);
+}
+.newsletter-inner {
+  display: grid; grid-template-columns: 1fr 1fr;
+  gap: 2rem; align-items: center;
+}
+@media (max-width: 800px) { .newsletter-inner { grid-template-columns: 1fr; } }
+
+.news-form {
+  display: grid; grid-template-columns: 1fr auto;
+  gap: .5rem;
+  background: #fff;
+  padding: .35rem .35rem .35rem 1rem;
+  border-radius: 999px;
+  border: 1px solid var(--line);
+}
+.news-form input {
+  border: 0; outline: none; background: transparent;
+  padding: .85rem 0;
+  font: inherit;
+  color: var(--ink);
+  min-width: 0;
+}
+.news-form input:focus-visible { outline: 0; }
+.news-form:focus-within { border-color: var(--ink); }
+.news-help {
+  grid-column: 1 / -1;
+  font-size: .75rem; color: var(--muted);
+  padding: .25rem 1rem 0;
+}
+.news-help.is-error { color: #b3261e; }
+.news-help.is-success { color: var(--accent); }
+
+/* ---------- Footer ---------- */
+.site-footer {
+  background: var(--ink);
+  color: #d6d3ce;
+  padding-top: 3rem;
+}
+.footer-grid {
+  display: grid; gap: 2rem;
+  grid-template-columns: 1.4fr repeat(3, 1fr);
+  padding-bottom: 2rem;
+}
+@media (max-width: 780px) { .footer-grid { grid-template-columns: 1fr 1fr; } }
+.footer-brand p { margin-top: .75rem; max-width: 32ch; color: #a9a59e; }
+.footer-brand .brand__mark { color: #fff; font-size: 1.6rem; }
+.site-footer h2 {
+  font-family: inherit;
+  font-size: .8rem; text-transform: uppercase; letter-spacing: .15em;
+  color: #fff; margin-bottom: 1rem; font-weight: 600;
+}
+.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: .55rem; }
+.site-footer a { color: #d6d3ce; font-size: .92rem; }
+.site-footer a:hover { color: #fff; }
+.footer-bottom {
+  display: flex; justify-content: space-between; gap: 1rem;
+  padding: 1.25rem 0;
+  border-top: 1px solid #2c2a27;
+  color: #807a72;
+}
+
+/* High contrast / forced colors */
+@media (forced-colors: active) {
+  .btn, .chip, .icon-btn, .cat-card, .product, .post, .deal {
+    border: 1px solid CanvasText;
+  }
+}
+
')

