const PRODUCTS = [
  { id: 'p1', name: 'Washed Linen Throw',  cat: 'home', catLabel: 'Home',      price: 89,  art: 'linear-gradient(135deg,#d8c8a8,#a48a64)',  tag: 'New' },
  { id: 'p2', name: 'Stoneware Mug Set',   cat: 'home', catLabel: 'Kitchen',   price: 42,  was: 56, art: 'radial-gradient(circle at 30% 30%,#ede7dc,#8a7350)', tag: 'Sale', sale: true },
  { id: 'p3', name: 'Merino Crew Sweater', cat: 'wear', catLabel: 'Wardrobe',  price: 138, art: 'linear-gradient(135deg,#2f5d4f,#1d3a31)' },
  { id: 'p4', name: 'Brass Desk Lamp',     cat: 'desk', catLabel: 'Workspace', price: 165, art: 'radial-gradient(circle at 70% 30%,#f3e4d0,#b89c7a)', tag: 'New' },
  { id: 'p5', name: 'Wide-leg Linen Pant', cat: 'wear', catLabel: 'Wardrobe',  price: 124, art: 'linear-gradient(135deg,#ede7dc,#b89c7a)' },
  { id: 'p6', name: 'Leather Notebook',    cat: 'desk', catLabel: 'Workspace', price: 38,  art: 'radial-gradient(circle at 30% 40%,#c8623c,#6b2a14)' },
  { id: 'p7', name: 'Cedar Soy Candle',    cat: 'home', catLabel: 'Home',      price: 32,  art: 'radial-gradient(circle at 50% 40%,#d8c8a8,#6b5239)' },
  { id: 'p8', name: 'Cotton Twill Cap',    cat: 'wear', catLabel: 'Wardrobe',  price: 48,  was: 62, art: 'linear-gradient(135deg,#2f5d4f,#142a23)', tag: 'Sale', sale: true },
];

const grid = document.getElementById('productGrid');
const status = document.getElementById('cartStatus');

function renderProducts(filter = 'all') {
  const items = PRODUCTS.filter(p => filter === 'all' || p.cat === filter);
  grid.innerHTML = items.map(p => `
    <li class="product">
      <div class="product__media">
        <div class="product__art" style="background:${p.art}"></div>
        ${p.tag ? `<span class="product__tag${p.sale ? ' product__tag--sale' : ''}">${p.tag}</span>` : ''}
        <button type="button" class="product__add"
          aria-label="Add ${p.name} to cart"
          data-id="${p.id}" data-name="${p.name}">
          <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
            <path d="M12 5v14M5 12h14"/>
          </svg>
        </button>
      </div>
      <div class="product__body">
        <span class="product__cat">${p.catLabel}</span>
        <a href="#" class="product__name">${p.name}</a>
        <p class="product__price">
          <span>$${p.price}</span>
          ${p.was ? `<del>$${p.was}</del>` : ''}
        </p>
      </div>
    </li>
  `).join('');
}

renderProducts();

// ----- Filters -----
document.querySelectorAll('.chip').forEach(chip => {
  chip.addEventListener('click', () => {
    document.querySelectorAll('.chip').forEach(c => {
      c.classList.remove('is-active');
      c.setAttribute('aria-pressed', 'false');
    });
    chip.classList.add('is-active');
    chip.setAttribute('aria-pressed', 'true');
    renderProducts(chip.dataset.filter);
  });
});

// ----- Cart -----
let cartCount = 0;
const cartBadge = document.getElementById('cartBadge');
const cartBtn   = document.getElementById('cartBtn');

grid.addEventListener('click', (e) => {
  const btn = e.target.closest('.product__add');
  if (!btn) return;
  cartCount += 1;
  cartBadge.textContent = String(cartCount);
  cartBtn.setAttribute('aria-label', `Cart, ${cartCount} item${cartCount === 1 ? '' : 's'}`);
  status.textContent = `${btn.dataset.name} added to cart. ${cartCount} item${cartCount === 1 ? '' : 's'} total.`;
});

// ----- Countdown -----
const target = new Date();
target.setDate(target.getDate() + 3);
target.setHours(23, 59, 59, 0);

const pad = n => String(n).padStart(2, '0');
const dEl = document.getElementById('cd-d');
const hEl = document.getElementById('cd-h');
const mEl = document.getElementById('cd-m');
const sEl = document.getElementById('cd-s');

function tick() {
  const diff = Math.max(0, target.getTime() - Date.now());
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff % 86400000) / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  dEl.textContent = pad(d);
  hEl.textContent = pad(h);
  mEl.textContent = pad(m);
  sEl.textContent = pad(s);
}
tick();
setInterval(tick, 1000);

// ----- Newsletter -----
const form = document.getElementById('newsForm');
const help = document.getElementById('newsHelp');
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const email = form.email.value.trim();
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  help.classList.remove('is-error', 'is-success');
  if (!ok) {
    help.classList.add('is-error');
    help.textContent = 'Please enter a valid email address.';
    form.email.focus();
    return;
  }
  help.classList.add('is-success');
  help.textContent = `Thanks — we'll be in touch at ${email}.`;
  form.reset();
});
